using Game.Server.Configuration;
using Game.Server.Data;
using Game.Shared;
using Game.Shared.Dtos;
using Game.Shared.Enums;
using Game.Shared.Models;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Options;

namespace Game.Server.Services;

public sealed partial class BattleRoundExecutor
{
    private async Task ApplyCombatSkillsAsync(Room room, List<BattleParticipant> aliveSlots, Monster monster,
        IReadOnlyDictionary<int, ElementType> mainWeaponElements,
        IReadOnlyDictionary<int, OperationPotionBonuses> operationBonuses,
        IReadOnlyCollection<int> autoCharacterIds, List<string> logs)
    {
        var characterIds = aliveSlots.Select(entry => entry.Character.Id).ToList();
        var battle = new BattleExecutionContext(room, monster,
            aliveSlots.Select(entry => new BattleParticipant(entry.Slot, entry.Character)).ToList(), mainWeaponElements,
            operationBonuses, logs, monsterCombatService is null ? null : () => monsterCombatService.InterruptCurrentIntentAsync(room, monster));
        await MageMechanics.RoundStartAsync(battle, Effects, mechanics);
        if (monster.Hp <= 0) return;
        var equipment = await dbContext.CharacterSkillSlots
            .Where(slot => characterIds.Contains(slot.CharacterId) && slot.SkillCode != null)
            .OrderBy(slot => slot.SlotIndex).ToListAsync();
        if (equipment.Count == 0) return;
        var cooldowns = await dbContext.BattleSkillCooldowns
            .Where(cooldown => cooldown.RoomId == room.Id && characterIds.Contains(cooldown.CharacterId)).ToListAsync();
        var purchasedNodes = await LegacyTalents.RanksAsync(characterIds);
        var professionLevels = (await dbContext.CharacterCombatProfessions
            .Where(entry => characterIds.Contains(entry.CharacterId)).ToListAsync())
            .GroupBy(entry => entry.CharacterId)
            .ToDictionary(group => group.Key, group => group.ToDictionary(entry => entry.ProfessionCode,
                entry => entry.Level, StringComparer.OrdinalIgnoreCase));
        var usedByCharacter = aliveSlots.ToDictionary(entry => entry.Character.Id,
            _ => new HashSet<string>(StringComparer.OrdinalIgnoreCase));

        async Task<bool> TryUseAsync(BattleParticipant participant, CharacterSkillSlot slot, bool automatic)
        {
            if (monster.Hp <= 0) return false;
            if (await Statuses.SkipBlockedActionAsync(room, participant.Character.Id)) return false;
            var levels = professionLevels.GetValueOrDefault(participant.Character.Id) ??
                new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            var skill = skillCatalog.Resolve(participant.Character, slot.SkillCode, levels);
            var used = usedByCharacter[participant.Character.Id];
            var ranks = purchasedNodes.GetValueOrDefault(participant.Character.Id) ?? new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
            if (skill is null || used.Contains(skill.Code)) return false;
            var cooldown = cooldowns.SingleOrDefault(entry => entry.CharacterId == participant.Character.Id && entry.SkillCode == skill.Code);
            if ((cooldown?.ReadyAtRound ?? skill.InitialCooldownRounds) > room.RoundNumber ||
                automatic && !slot.AutoUseEnabled) return false;
            var snapshot = await _skillSnapshots.CaptureAsync(room, monster, skill, participant.Character.Id,
                aliveSlots.Select(entry => (entry.Slot, entry.Character)), levels, cooldowns);
            if (automatic && !SkillBattlePolicy.MeetsAutoCondition(skill, snapshot, slot.AutoConditionOverride,
                    slot.AutoHpThresholdPercent, LegacySkillTalentAdapter.AutoSelfCleanse(skill, ranks))) return false;
            var chosenTargetId = automatic ? null : SkillQueueRules.TargetCharacterId(participant.Slot, slot.SlotIndex);
            if (!SkillBattlePolicy.HasApplicableEffect(skill, snapshot, chosenTargetId)) return false;

            var source = BattleActor.ForCharacter(battle.Party.Single(entry => entry.Character.Id == participant.Character.Id),
                battle.StatsFor(participant.Character));
            var cast = new BattleCastExecution(battle, skill, source)
            {
                ChosenTargetId = chosenTargetId, Cooldowns = cooldowns, ProfessionLevels = levels
            };
            var mechanic = _professionMechanics.For(skill);
            if (ranks.Count > 0) mechanic = new LegacySkillTalentAdapter(mechanic, ranks,
                (characterId, code, duration) => LegacyTalents.GrantEchoAsync(room, characterId, code, duration, cast.Skill.Code));
            var result = await Effects.ExecuteAsync(cast, mechanic);
            if (!result.Applied) return false;
            if (cooldown is null)
            {
                cooldown = new BattleSkillCooldown { RoomId = room.Id, CharacterId = participant.Character.Id, SkillCode = skill.Code };
                cooldowns.Add(cooldown);
                dbContext.BattleSkillCooldowns.Add(cooldown);
            }
            cooldown.ReadyAtRound = checked(room.RoundNumber + skill.CooldownRounds + 1);
            used.Add(skill.Code);
            return true;
        }

        foreach (var participant in aliveSlots)
        {
            var characterEquipment = equipment.Where(slot => slot.CharacterId == participant.Character.Id);
            foreach (var slot in characterEquipment.Where(slot => (participant.Slot.PendingSkillSlotMask & SkillRules.SlotMask(slot.SlotIndex)) != 0))
            {
                if (monster.Hp <= 0) break;
                await TryUseAsync(participant, slot, automatic: false);
            }
            if (monster.Hp <= 0) break;
        }
        foreach (var participant in aliveSlots)
        {
            if (!autoCharacterIds.Contains(participant.Character.Id)) continue;
            var characterEquipment = equipment.Where(slot => slot.CharacterId == participant.Character.Id);
            foreach (var slot in characterEquipment)
            {
                if (monster.Hp <= 0) break;
                if ((participant.Slot.PendingSkillSlotMask & SkillRules.SlotMask(slot.SlotIndex)) == 0)
                    await TryUseAsync(participant, slot, automatic: true);
            }
            if (monster.Hp <= 0) break;
        }
    }

}

using Game.Server.Configuration;
using Game.Server.Data;
using Game.Shared;
using Game.Shared.Dtos;
using Game.Shared.Enums;
using Game.Shared.Models;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Options;

namespace Game.Server.Services;

public sealed partial class BattleRoundExecutor
{
    private async Task ApplySoulImprintsAsync(Room room, List<BattleParticipant> aliveSlots, Monster monster,
        IReadOnlyDictionary<int, OperationPotionBonuses> operationBonuses,
        IReadOnlyCollection<int> autoCharacterIds, List<string> logs)
    {
        if (soulImprintCatalog is null || aliveSlots.Count == 0 || monster.Hp <= 0) return;
        var characterIds = aliveSlots.Select(entry => entry.Character.Id).ToList();
        var equipped = await dbContext.CharacterSoulImprints.Where(entry =>
            characterIds.Contains(entry.CharacterId) && entry.EquippedSlotIndex == SoulImprintRules.SlotIndex).ToListAsync();
        if (equipped.Count == 0) return;
        var cooldownCodes = equipped.Select(entry => SoulImprintRules.CooldownCode(entry.SoulImprintCode)).ToList();
        var cooldowns = await dbContext.BattleSkillCooldowns.Where(entry => entry.RoomId == room.Id &&
            characterIds.Contains(entry.CharacterId) && cooldownCodes.Contains(entry.SkillCode)).ToListAsync();

        var battle = new BattleExecutionContext(room, monster,
            aliveSlots.Select(entry => new BattleParticipant(entry.Slot, entry.Character)).ToList(),
            new Dictionary<int, ElementType>(), operationBonuses, logs);
        foreach (var participant in aliveSlots.OrderBy(entry => entry.Slot.SlotIndex))
        {
            if (monster.Hp <= 0) break;
            var imprint = equipped.SingleOrDefault(entry => entry.CharacterId == participant.Character.Id);
            var definition = soulImprintCatalog.Find(imprint?.SoulImprintCode);
            if (imprint is null || definition is null) continue;
            var automatic = !participant.Slot.IsSoulImprintQueued && imprint.AutoUseEnabled &&
                autoCharacterIds.Contains(participant.Character.Id);
            if (!participant.Slot.IsSoulImprintQueued && !automatic) continue;
            var cooldownCode = SoulImprintRules.CooldownCode(definition.Code);
            var cooldown = cooldowns.SingleOrDefault(entry => entry.CharacterId == participant.Character.Id &&
                entry.SkillCode == cooldownCode);
            var readyAtRound = cooldown?.ReadyAtRound ?? definition.InitialCooldownRounds;
            if (readyAtRound > room.RoundNumber ||
                !await CanSoulImprintApplyAsync(room, monster, definition, participant, aliveSlots) ||
                automatic && !await MeetsSoulImprintAutoConditionAsync(room, monster, definition, participant, aliveSlots)) continue;
            if (await Statuses.SkipBlockedActionAsync(room, participant.Character.Id)) continue;

            var soulSource = BattleActor.ForCharacter(new(participant.Slot, participant.Character), battle.StatsFor(participant.Character));
            using var soulAction = _events.ActionScope(soulSource, definition.Code, definition.Name, BattleActionKind.SoulImprint);
            async Task<int> DealSoulDamageAsync()
            {
                var damageResult = await Effects.Damage.CharacterDamageAsync(battle,
                    soulSource, BattleSkillEffect.Damage(definition.PowerPercent),
                    BattleDamageOrigin.Skill, true, damageElement: definition.Element);
                var damage = damageResult.CalculatedAmount;
                var critical = damageResult.IsCritical;
                logs.Add($"{participant.Slot.SlotIndex}号位 {participant.Character.Name} 释放魂印「{definition.Name}」攻击 {monster.Name}，造成 {damage} 点{WeaponRules.ElementName(definition.Element)}属性伤害{(critical ? "（暴击）" : "")}。");
                return damage;
            }

            switch (definition.EffectType)
            {
                case SoulImprintEffectType.DamageArmorBreak:
                    await DealSoulDamageAsync();
                    if (monster.Hp > 0 && monsterCombatService is not null)
                        await monsterCombatService.ApplyStatusAsync(room, "Monster", monster.Id, definition.StatusCode!,
                            definition.DurationRounds, logs, monster.Name, source: new("Character", participant.Character.Id, definition.Code));
                    break;
                case SoulImprintEffectType.DamageEcho:
                {
                    var damage = await DealSoulDamageAsync();
                    var calculatedEcho = (int)decimal.Floor(damage * definition.SecondaryPowerPercent / 100m);
                    var echo = Math.Min(monster.Hp, calculatedEcho);
                    if (echo > 0)
                    {
                        var before = monster.Hp;
                        monster.Hp -= echo;
                        using var followUp = _events.ActionScope(soulSource, definition.Code, "魂印毒蚀", BattleActionKind.FollowUp);
                        _events.Hp(room, BattleEventKind.Damage, soulSource, battle.Enemy, calculatedEcho, echo, before);
                        logs.Add($"魂印毒蚀对 {monster.Name} 追加 {echo} 点无视防御伤害。");
                    }
                    break;
                }
                case SoulImprintEffectType.Interrupt:
                    await DealSoulDamageAsync();
                    if (monster.Hp > 0 && monsterCombatService is not null &&
                        await monsterCombatService.InterruptCurrentIntentAsync(room, monster))
                    {
                        _events.Utility(room, BattleEventKind.Interrupt, battle.Enemy, label: "打断");
                        logs.Add($"魂印「{definition.Name}」打断了 {monster.Name} 的行动。");
                    }
                    break;
                case SoulImprintEffectType.CooldownReduction:
                {
                    var reduction = Math.Max(1, definition.SecondaryPowerPercent);
                    var affected = await dbContext.BattleSkillCooldowns.Where(entry => entry.RoomId == room.Id &&
                        entry.CharacterId == participant.Character.Id &&
                        !entry.SkillCode.StartsWith(SoulImprintRules.CooldownPrefix) &&
                        entry.ReadyAtRound > room.RoundNumber).ToListAsync();
                    foreach (var skillCooldown in affected)
                        skillCooldown.ReadyAtRound = Math.Max(room.RoundNumber, skillCooldown.ReadyAtRound - reduction);
                    if (affected.Count > 0) _events.Utility(room, BattleEventKind.Cooldown, soulSource, reduction, $"冷却缩短 {reduction} 回合");
                    logs.Add($"{participant.Slot.SlotIndex}号位 {participant.Character.Name} 释放魂印「{definition.Name}」，{affected.Count} 个职业技能的剩余冷却缩短 {reduction} 回合。");
                    break;
                }
                case SoulImprintEffectType.HealCleanse:
                    foreach (var target in aliveSlots.Where(entry => entry.Character.Hp > 0))
                    {
                        var hpBefore = target.Character.Hp;
                        var healingTarget = BattleActor.ForCharacter(new(target.Slot, target.Character), battle.StatsFor(target.Character));
                        var calculated = BattleDamageService.CalculateHealing(soulSource, healingTarget,
                            new(BattleEffectKind.Heal, BattleEffectTarget.ForCharacter("AllAlive"), HealMaxHpPercent: definition.PowerPercent),
                            applyHealingBonuses: false);
                        var heal = BattleDamageService.RestoreHp(healingTarget, calculated);
                        if (heal > 0)
                        {
                            _events.Hp(room, BattleEventKind.Heal, soulSource, healingTarget, calculated, heal, hpBefore);
                            logs.Add($"魂印「{definition.Name}」为 {target.Slot.SlotIndex}号位 {target.Character.Name} 恢复 {heal} 点生命值。");
                        }
                        if (monsterCombatService is not null)
                        {
                            for (var count = 0; count < definition.SecondaryPowerPercent; count++)
                            {
                                var removed = await monsterCombatService.RemoveFirstStatusAsync(room, "Character",
                                    [target.Character.Id], false);
                                if (removed is null) break;
                                logs.Add($"魂印「{definition.Name}」移除了 {target.Slot.SlotIndex}号位 {target.Character.Name} 的 {removed.Name}。");
                                await Effects.Damage.ObserveCleanseAsync(battle, target.Character.Id, removed.Code);
                            }
                        }
                    }
                    break;
                case SoulImprintEffectType.GuardCounter:
                    if (monsterCombatService is not null)
                        await monsterCombatService.ApplyStatusAsync(room, "Character", participant.Character.Id,
                            definition.StatusCode!, definition.DurationRounds, logs,
                            $"{participant.Slot.SlotIndex}号位 {participant.Character.Name}", source: new("Character", participant.Character.Id, definition.Code));
                    await DealSoulDamageAsync();
                    break;
            }

            if (cooldown is null)
            {
                cooldown = new BattleSkillCooldown
                {
                    RoomId = room.Id, CharacterId = participant.Character.Id, SkillCode = cooldownCode
                };
                cooldowns.Add(cooldown);
                dbContext.BattleSkillCooldowns.Add(cooldown);
            }
            cooldown.ReadyAtRound = checked(room.RoundNumber + definition.CooldownRounds + 1);
        }
    }

    public async Task<bool> CanSoulImprintApplyAsync(Room room, Monster monster,
        SoulImprintDefinitionOptions definition, BattleParticipant participant, IReadOnlyCollection<BattleParticipant> aliveSlots)
    {
        if (monster.Hp <= 0) return false;
        return definition.EffectType switch
        {
            SoulImprintEffectType.Interrupt => monsterCombatService is not null &&
                await monsterCombatService.CanInterruptCurrentIntentAsync(room, monster),
            SoulImprintEffectType.HealCleanse => aliveSlots.Any(entry => entry.Character.Hp > 0 &&
                entry.Character.Hp < TalentRules.EffectiveMaxHp(entry.Character)) || monsterCombatService is not null &&
                await monsterCombatService.HasRemovableStatusAsync(room, "Character",
                    aliveSlots.Select(entry => entry.Character.Id).ToList(), false),
            SoulImprintEffectType.CooldownReduction => await dbContext.BattleSkillCooldowns.AnyAsync(entry =>
                entry.RoomId == room.Id && entry.CharacterId == participant.Character.Id &&
                !entry.SkillCode.StartsWith(SoulImprintRules.CooldownPrefix) && entry.ReadyAtRound > room.RoundNumber),
            _ => true
        };
    }

    private async Task<bool> MeetsSoulImprintAutoConditionAsync(Room room, Monster monster,
        SoulImprintDefinitionOptions definition, BattleParticipant participant,
        IReadOnlyCollection<BattleParticipant> aliveSlots)
    {
        switch (definition.EffectType)
        {
            case SoulImprintEffectType.HealCleanse:
                if (monsterCombatService is not null &&
                    await monsterCombatService.HasRemovableStatusAsync(room, "Character",
                        aliveSlots.Select(entry => entry.Character.Id).ToList(), false))
                    return true;
                return aliveSlots.Any(entry => entry.Character.Hp > 0 &&
                    (long)entry.Character.Hp * 100 <=
                    (long)TalentRules.EffectiveMaxHp(entry.Character) * definition.AutoHpThresholdPercent);
            case SoulImprintEffectType.GuardCounter:
            {
                if (monsterCombatService is null) return false;
                var intent = await monsterCombatService.EnsureIntentAsync(room, monster);
                return intent is { IsInterrupted: false } &&
                    (intent.TargetType == "AllAlive" || intent.TargetCharacterId == participant.Character.Id);
            }
            default:
                return true;
        }
    }

}

using Game.Server.Configuration;
using Game.Server.Data;
using Game.Shared;
using Game.Shared.Dtos;
using Game.Shared.Enums;
using Game.Shared.Models;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.Options;

namespace Game.Server.Services;

public enum BattleRoundOutcome { Continue, MonsterDefeated, PartyDefeated }

/// <summary>
/// Runs combat actions against tracked state without saving, awarding rewards, changing waves,
/// or scheduling rooms. The caller owns the settlement/event scopes and commits the whole round.
/// </summary>
public sealed partial class BattleRoundExecutor(GameDbContext dbContext, ConsumableCatalog consumableCatalog,
    SkillCatalog skillCatalog, BattleStatusService statuses, BattleEffectExecutor effects,
    MonsterCombatService? monsterCombatService = null, WeaponCatalog? weaponCatalog = null,
    SoulImprintCatalog? soulImprintCatalog = null, Random? random = null, ProfessionMechanicCatalog? mechanics = null)
{
    private readonly SkillBattleSnapshotFactory _skillSnapshots = new(dbContext, skillCatalog, monsterCombatService, mechanics);
    private readonly LegacyBattleTalentService LegacyTalents = new(dbContext, skillCatalog, statuses);
    private readonly ProfessionMechanicRegistry _professionMechanics = new(mechanics);
    private BattleStatusService Statuses => statuses;
    private BattleEffectExecutor Effects => effects;
    private BattleEventCollector _events => effects.Events;

    public async Task<BattleRoundOutcome> ExecuteAsync(Room room, Monster monster, List<BattleParticipant> slots,
        IReadOnlyCollection<int> autoCharacterIds, List<string> logs)
    {
        if (monsterCombatService is not null)
            await monsterCombatService.Phases.BeginRoundAsync(room, monster, logs, slots);
        var aliveSlots = slots.Where(entry => entry.Character.Hp > 0).OrderBy(entry => entry.Slot.SlotIndex).ToList();
        var combatParticipants = slots.OrderBy(entry => entry.Slot.SlotIndex).ToList();
        var characterIds = aliveSlots.Select(entry => entry.Character.Id).ToList();
        var operationBonuses = await ApplyOperationPotionsAsync(room, aliveSlots, logs);
        await UpdateTemporaryWeaponBonusesAsync(room, aliveSlots);
        await ApplyCombatBuffsAsync(room, aliveSlots, logs);
        await UpdateTemporaryWeaponBonusesAsync(room, aliveSlots);
        var mainWeaponElements = await dbContext.CharacterWeapons
            .Where(weapon => characterIds.Contains(weapon.CharacterId) && weapon.EquippedSlotIndex == WeaponRules.MainSlotIndex)
            .ToDictionaryAsync(weapon => weapon.CharacterId, weapon => weapon.Element);
        var pendingTalentEcho = new Dictionary<int, decimal>();
        foreach (var entry in aliveSlots)
        {
            pendingTalentEcho[entry.Character.Id] = await Statuses.IsActionBlockedAsync(room, entry.Character.Id)
                ? 0 : await LegacyTalents.ConsumeEchoAsync(room, entry.Character.Id);
        }
        await ApplySoulImprintsAsync(room, aliveSlots, monster, operationBonuses, autoCharacterIds, logs);
        await ApplyCombatSkillsAsync(room, aliveSlots, monster, mainWeaponElements,
            operationBonuses, autoCharacterIds, logs);
        var battle = new BattleExecutionContext(room, monster,
            slots.Select(entry => new BattleParticipant(entry.Slot, entry.Character)).ToList(), mainWeaponElements, operationBonuses, logs);
        foreach (var entry in aliveSlots)
        {
            if (monster.Hp <= 0) break;
            if (await Statuses.SkipBlockedActionAsync(room, entry.Character.Id))
            {
                logs.Add($"{entry.Slot.SlotIndex}号位 {entry.Character.Name} 本回合因冻结跳过攻击。");
                continue;
            }
            var stats = battle.StatsFor(entry.Character);
            var talentEcho = pendingTalentEcho[entry.Character.Id];
            var healthPercent = WeaponCombatRules.HealthDamagePercent(entry.Character.Hp, stats.MaxHp,
                stats.StaminaPercent, stats.EnmityPercent);
            var adrenalineChance = monsterCombatService is null ? 0m :
                await monsterCombatService.GetModifierAsync(room, "Character", entry.Character.Id, "DoubleAttackChancePercent");
            var coordinatedEcho = monsterCombatService is null ? 0 :
                await monsterCombatService.Statuses.MechanicPowerAsync(room, "Character", entry.Character.Id, BattleStatusMechanic.HunterCoordinated);
            var hits = WeaponCombatRules.RollPercent(stats.DoubleAttackChancePercent + adrenalineChance, random) ? 2 : 1;
            for (var hit = 0; hit < hits && monster.Hp > 0; hit++)
            {
                var source = BattleActor.ForCharacter(new(entry.Slot, entry.Character), stats);
                using var attackAction = _events.ActionScope(source, "normal-attack", hit == 0 ? "普通攻击" : "二连击", BattleActionKind.NormalAttack);
                var damageResult = await Effects.Damage.CharacterDamageAsync(battle, source,
                    BattleSkillEffect.Damage(100), BattleDamageOrigin.NormalAttack, true, healthPercent);
                var damage = damageResult.CalculatedAmount;
                var critical = damageResult.IsCritical;
                logs.Add($"{entry.Slot.SlotIndex}号位 {entry.Character.Name} {(hit == 0 ? "普通攻击" : "二连击")} {monster.Name}，造成 {damage} 点伤害{(critical ? "（暴击）" : "")}。");
                var echo = WeaponCombatRules.EchoDamage(damage,
                    stats.NormalEchoPercent + talentEcho + coordinatedEcho);
                if (monster.Hp > 0 && echo > 0)
                {
                    var before = monster.Hp;
                    monster.Hp = Math.Max(0, monster.Hp - echo);
                    using var followUp = _events.ActionScope(source, "normal-echo", "普攻追击", BattleActionKind.FollowUp);
                    _events.Hp(room, BattleEventKind.Damage, source, battle.Enemy, echo, before - monster.Hp, before,
                        element: mainWeaponElements.TryGetValue(source.Id, out var echoElement) ? echoElement : null, modifier: WeaponCombatRules.ElementAttackPercent(
                            mainWeaponElements.TryGetValue(source.Id, out var echoModifierElement) ? echoModifierElement : null, monster.Element, stats.ElementAdvantagePercent));
                    logs.Add($"{entry.Slot.SlotIndex}号位 {entry.Character.Name} 对 {monster.Name} 造成 {echo} 点普攻追击伤害。");
                    await Effects.Damage.ObserveDirectDamageAsync(battle,
                        mainWeaponElements.TryGetValue(source.Id, out var waterEchoElement) ? waterEchoElement : null, before - monster.Hp);
                }
            }
            if (monster.Hp <= 0) break;
        }
        if (monster.Hp <= 0)
        {
            // A player kill completes healing auras, but skips enemy damage and hostile periodic effects.
            if (monsterCombatService is not null)
                await monsterCombatService.ResolveEndOfRoundAsync(room, monster, combatParticipants, logs,
                    operationBonuses, healingOnly: true);
            await LegacyTalents.VictoryAsync(battle, characterIds);
            if (monsterCombatService is not null) await monsterCombatService.Phases.EndRoundAsync(room, monster, logs);
            return BattleRoundOutcome.MonsterDefeated;
        }

        await ApplyCombatConsumablesAsync(room, aliveSlots, logs);
        if (!slots.Any(entry => entry.Character.Hp > 0)) return BattleRoundOutcome.PartyDefeated;
        if (monsterCombatService is not null)
        {
            await monsterCombatService.ExecuteIntentAsync(room, monster, combatParticipants,
                mainWeaponElements, logs, operationBonuses);
            await monsterCombatService.ResolveEndOfRoundAsync(room, monster, combatParticipants, logs,
                operationBonuses);
            await monsterCombatService.Phases.EndRoundAsync(room, monster, logs);
        }
        else
        {
            var target = slots.Where(entry => entry.Character.Hp > 0).OrderBy(entry => entry.Slot.SlotIndex).First();
            using var attackAction = _events.ActionScope(battle.Enemy, "basic-attack", "普通攻击", BattleActionKind.NormalAttack);
            var damageResult = await Effects.Damage.MonsterDamageAsync(battle, BattleActor.ForCharacter(target, battle.StatsFor(target.Character)),
                new(BattleEffectKind.Damage, BattleEffectTarget.ForMonster("Front")), false);
            logs.Add($"{monster.Name} 普通攻击 {target.Slot.SlotIndex}号位 {target.Character.Name}，造成 {damageResult.CalculatedAmount} 点伤害。");
            await Statuses.ResolveEndOfRoundAsync(room, monster, combatParticipants, logs, operationBonuses);
        }
        // A counter or periodic effect can defeat the monster during the enemy phase.
        if (monster.Hp <= 0)
        {
            await LegacyTalents.VictoryAsync(battle, characterIds);
            return BattleRoundOutcome.MonsterDefeated;
        }
        return slots.Any(entry => entry.Character.Hp > 0) ? BattleRoundOutcome.Continue : BattleRoundOutcome.PartyDefeated;
    }

    /// <summary>Runs after the caller decides the wave/outcome and before advancing the round number.</summary>
    public async Task FinishRoundEffectsAsync(Room room, IReadOnlyList<BattleParticipant> party)
    {
        await CaptureConsumableExpiryAsync(room);
        await effects.Guards.ClearRoundAsync(room, party.Select(entry => entry.Character.Id));
    }
}

