const assert=require('assert/strict');
const mirror='light-deep-lv2-mirror',reward='light-deep-lv2-imbalance';
module.exports=function audit(s,route){
 const boss='monster:5:1',phase=s.MonsterPhaseRounds.filter(p=>p.MonsterId===5).at(-1);
 assert.equal(phase.Activations,1);assert.equal(phase.Breaks,route==='unhandled'?0:1);assert.equal(phase.Expiries,route==='unhandled'?1:0);
 if(route==='dark'){assert.equal(phase.LinkedHits,3);assert.equal(phase.LastBreakRound-phase.LastActivationRound,2);}
 if(route==='dispel'||route==='unhandled')assert.equal(phase.LinkedHits,0);
 const mins=Array(5).fill(100),activation=[],rewards=[],expiries=[],weakens=[],reflects=[],bossCasts=new Set(),starts={};
 let strength=0,broken=false;
 for(const t of s.RoundTrace){
  const r=t.Data.RoundNumber-1,perActor=new Map(),used=new Set();
  assert(t.Data.OperationPotions.every(p=>!p.ItemCode));assert.equal(t.Data.ConsumableBuffs.length,0);
  for(const e of t.Data.Events){
   if(starts[e.Monster]===undefined)starts[e.Monster]=r;
   if(e.Target?.startsWith('character:')&&e.HpAfter!==null&&e.TargetMaxHp>0)mins[+e.Target.split(':')[1]-1]=Math.min(mins[+e.Target.split(':')[1]-1],100*e.HpAfter/e.TargetMaxHp);
   if(e.Source===boss&&e.ActionKind===0&&['light-deep-lv1-warden-pierce','light-deep-lv1-warden-nova'].includes(e.SkillCode)&&!(e.Kind===2&&[2,3,4].includes(e.StatusChange))){
    const local=r-starts[boss]+1,[first,period]=e.SkillCode.endsWith('pierce')?[2,4]:[4,4];
    assert(local>=first&&(local-first)%period===0,'Boss local skill clock');bossCasts.add(r+':'+e.SkillCode);
   }
   assert(!(e.Source===boss&&e.SkillCode==='light-deep-lv1-warden-ward'),'Boss LV1 ward must be replaced');
   assert(!e.SkillCode?.startsWith('depth-placeholder-')&&!e.SkillCode?.startsWith('endgame-'),'No placeholders/enrage');
   if(e.Status?.Code===mirror&&e.StatusChange===0){activation.push({Round:r,Stacks:e.CountAfter,ExpiresAfterRound:e.Status.ExpiresAfterRound});strength=e.CountAfter;assert.equal(strength,3);assert.equal(e.Status.AppliedRound,r);assert.equal(e.Status.ExpiresAfterRound,r+3);}
   if(e.Status?.Code===mirror&&e.StatusChange===2){
    const before=t.Data.Events.findLast(x=>x.Sequence<e.Sequence&&x.Kind===0&&x.Source===e.Source);
    assert(before&&before.Element===5&&before.ActualAmount>0&&before.Target===boss,'Actual attributable Dark hit');
    assert([0,1,3,6].includes(before.ActionKind),'Only direct origins');assert(!used.has(e.Source),'Per-actor per-round dedup');used.add(e.Source);
    assert.equal(e.CountBefore-e.CountAfter,1);assert.equal(e.CountBefore,strength);strength=e.CountAfter;
    weakens.push({Round:r,Actor:e.Source,Skill:before.SkillCode,StacksAfter:strength});if(strength===0)broken=true;
   }
   if(e.Kind===4&&e.Status?.Code===mirror){broken=true;strength=0;assert.equal(e.SkillCode,'mage-spellbreak');}
   if(e.Status?.Code===mirror&&e.StatusChange===4){strength=0;expiries.push(r);}
   if(e.Status?.Code===reward&&e.StatusChange===0){rewards.push({Round:r,ExpiresAfterRound:e.Status.ExpiresAfterRound});assert.equal(r,phase.LastBreakRound+1);assert.equal(e.Status.ExpiresAfterRound,r+2);}
   if(e.SkillCode==='light-reflection'&&e.Kind===0){
    assert.equal(e.Source,boss);assert.equal(e.ActionKind,6);assert.equal(e.Element,null);assert.equal(e.ElementModifier,0);assert.equal(e.IsCritical,false);
    assert(r>=phase.LastActivationRound&&r<=phase.LastActivationRound+3&&strength>0&&!broken,'Reflection only inside live phase');
    const total=(perActor.get(e.Target)??0)+e.CalculatedAmount;perActor.set(e.Target,total);
    const hp=s.Builds[+e.Target.split(':')[1]-1].Stats.MaxHp;assert(total<=Math.floor(hp*.15),'Actual reflection cannot exceed initial raw cap');
    reflects.push({Round:r,Actor:e.Target,Amount:e.ActualAmount,StrengthAtResolution:strength});
   }
  }
 }
 assert.equal(activation.length,1);assert.equal(activation[0].Round,phase.LastActivationRound);
 const prior=s.RoundTrace.find(t=>t.Data.RoundNumber-1===phase.LastActivationRound-1).Data.Monsters.find(m=>m.Actor===boss);assert(prior.Hp<=prior.MaxHp*.70);
 const firstCross=s.RoundTrace.find(t=>t.Data.CurrentWaveNumber===5&&t.Data.Monsters.some(m=>m.Actor===boss&&m.Hp<=m.MaxHp*.70));assert.equal(firstCross.Data.RoundNumber,phase.LastActivationRound);
 if(route==='unhandled'){assert.equal(rewards.length,0);assert.deepEqual(expiries,[phase.LastActivationRound+3]);assert.equal(phase.LastExpiryRound,phase.LastActivationRound+3);}
 else{assert.equal(rewards.length,1);assert.equal(expiries.length,0);assert(phase.LastBreakRound>=phase.LastActivationRound&&phase.LastBreakRound<=phase.LastActivationRound+3);}
 assert.equal(weakens.length,phase.LinkedHits);
 return {Activation:activation[0],BreakWindowRound:phase.LastBreakRound===null?null:phase.LastBreakRound-phase.LastActivationRound+1,LinkedHits:phase.LinkedHits,WeakeningActions:weakens,Rewards:rewards,NaturalExpiryRounds:expiries,ReflectionEvents:reflects.length,ReflectedDamage:reflects.reduce((n,e)=>n+e.Amount,0),ReflectedDamageBySlot:Array.from({length:5},(_,i)=>reflects.filter(e=>e.Actor==='character:'+(i+1)).reduce((n,e)=>n+e.Amount,0)),MinimumHpPercentBySlot:mins,HpTriggerNextFullRound:true,RewardThreeFullRounds:true,PerActorDarkDedup:true,ActualReflectionWithinRawCeiling:true,NoReflectionAfterBreak:true,BossLocalCadence:true,NoLegacyWardOrPlaceholders:true};
};
